package com.coraline.feast;
import java.util.UUID;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.nbt.CompoundTag;
@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class WybieAdventureGameTests {
    private static CompoundTag ready(){var n=WybieAdventureLedger.begin(UUID.randomUUID(),UUID.randomUUID(),7,41);WybieAdventureLedger.mode(n,WybieAdventureLedger.Mode.INTRO);n.putInt("IntroLength",471);n.putInt("IntroElapsed",471);WybieAdventureLedger.introFinished(n);return n;}
    @GameTest(template="empty") public static void introNeverSpendsAdventureTime(GameTestHelper h){var n=WybieAdventureLedger.begin(UUID.randomUUID(),UUID.randomUUID(),7,1);for(int i=0;i<1000;i++)WybieAdventureLedger.tick(n);h.assertTrue(n.getInt("Remaining")==24000,"Door delay must not spend adventure time");WybieAdventureLedger.mode(n,WybieAdventureLedger.Mode.INTRO);n.putInt("IntroLength",471);n.putInt("IntroElapsed",470);h.assertTrue(!WybieAdventureLedger.introFinished(n),"One tick early must not start");n.putInt("IntroElapsed",471);h.assertTrue(WybieAdventureLedger.introFinished(n),"Actual recording completion starts timer");WybieAdventureLedger.tick(n);h.assertTrue(n.getInt("Remaining")==23999,"Starts once, at full duration");h.assertTrue(!WybieAdventureLedger.introFinished(n),"Finish replay cannot reset clock");h.succeed();}
    @GameTest(template="empty") public static void restartAndModeChangesRetainClock(GameTestHelper h){var n=ready();for(int i=0;i<4321;i++)WybieAdventureLedger.tick(n);n=n.copy();for(var mode:new WybieAdventureLedger.Mode[]{WybieAdventureLedger.Mode.LEAD,WybieAdventureLedger.Mode.FOLLOW,WybieAdventureLedger.Mode.SEARCH}){WybieAdventureLedger.mode(n,mode);WybieAdventureLedger.tick(n);}h.assertTrue(n.getInt("Remaining")==19676,"Save and mode changes preserve remaining ticks");for(int i=0;i<25000;i++)WybieAdventureLedger.tick(n);h.assertTrue(n.getInt("Remaining")==0,"Clock clamps at zero, no grace period or overflow");h.succeed();}
    @GameTest(template="empty") public static void currentResetsBestNeverDoes(GameTestHelper h){var n=ready();WybieAdventureLedger.startRun(n);h.assertTrue(WybieAdventureLedger.checkpoint(n,2,8,100)==0,"Out-of-order checkpoint rejected");for(int i=1;i<8;i++)WybieAdventureLedger.checkpoint(n,i,8,150);WybieAdventureLedger.checkpoint(n,0,8,100);int best=n.getInt("BestScore");h.assertTrue(best>=1400,"Full circuit gives skill points and a lap bonus");WybieAdventureLedger.failRun(n,"crash");h.assertTrue(n.getInt("CurrentScore")==0&&n.getInt("Combo")==0,"Failure resets only current run");h.assertTrue(n.getInt("BestScore")==best,"Failure retains best");WybieAdventureLedger.startRun(n);WybieAdventureLedger.checkpoint(n,1,8,100);WybieAdventureLedger.failRun(n,"leave");h.assertTrue(n.getInt("BestScore")==best,"Lesser run never overwrites best");h.assertTrue(n.getInt("Remaining")==24000,"Retries never change remaining time");h.succeed();}
    @GameTest(template="empty") public static void captureRequiresPhysicalOwnerAndRealOffense(GameTestHelper h){for(int bits=0;bits<64;bits++){boolean pending=(bits&1)!=0,started=(bits&2)!=0,contact=(bits&4)!=0,owner=(bits&8)!=0,area=(bits&16)!=0,evidence=(bits&32)!=0;boolean actual=WybieAdventureLedger.banQualifies(pending,started,contact,owner,area,evidence);h.assertTrue(actual==(pending&&started&&contact&&owner&&(area||evidence)),"Capture truth table case "+bits);}h.succeed();}
    @GameTest(template="empty") public static void checkpointsRequireDirectionAndWidth(GameTestHelper h){h.assertTrue(WybieBicyclePhysics.forwardCrossing(-1,0,1,0,0,0,1,0,1),"Forward crossing inside gate accepted");h.assertTrue(!WybieBicyclePhysics.forwardCrossing(1,0,-1,0,0,0,1,0,1),"Backward crossing rejected");h.assertTrue(!WybieBicyclePhysics.forwardCrossing(-1,2,1,2,0,0,1,0,1),"Going around the gate rejected");h.assertTrue(!WybieBicyclePhysics.forwardCrossing(0,0,0,0,0,0,1,0,1),"Standing still cannot score");h.succeed();}
    @GameTest(template="empty") public static void bicyclePhysicsBoundsAndBrakes(GameTestHelper h){double speed=0;float yaw=0;for(int i=0;i<500;i++){var motion=WybieBicyclePhysics.step(speed,yaw,1,1,false);h.assertTrue(motion.speed()<=.340001,"Speed bounded");h.assertTrue(Math.abs(WybieBicyclePhysics.wrap(motion.yaw()-yaw))<6,"Turning never snaps");speed=motion.speed();yaw=motion.yaw();}for(int i=0;i<20;i++)speed=WybieBicyclePhysics.step(speed,0,0,0,true).speed();h.assertTrue(speed==0,"Brake reaches rest");h.assertTrue(WybieBicyclePhysics.step(Double.NaN,0,1,1,false).speed()==0,"Nonfinite packet/state rejected");h.assertTrue(WybieBicyclePhysics.step(0,90,0,1,false).yaw()==90,"Stationary bicycle does not pivot in place");h.succeed();}
    @GameTest(template="empty") public static void rewardsWarningsAndOwnerIsolation(GameTestHelper h){int[] points={0,499,500,1499,1500,2999,3000,4999,5000};int[] tiers={0,0,1,1,2,2,3,3,4};for(int i=0;i<points.length;i++)h.assertTrue(WybieAdventureLedger.rewardTier(points[i])==tiers[i],"Reward tier boundary "+points[i]);var n=ready();h.assertTrue(WybieAdventureLedger.owned(n,n.getUUID("Owner"),n.getUUID("Door"),7),"Exact lease accepted");h.assertTrue(!WybieAdventureLedger.owned(n,UUID.randomUUID(),n.getUUID("Door"),7),"Helper cannot control session");n.putInt("Remaining",6000);h.assertTrue(WybieAdventureLedger.warning(n,6000,"five"),"First threshold warning");h.assertTrue(!WybieAdventureLedger.warning(n,6000,"five"),"Warning not spammed");n=n.copy();h.assertTrue(!WybieAdventureLedger.warning(n,6000,"five"),"Warning remembered on restart");h.succeed();}
}
